<?php
require_once __DIR__ . '/_automation_helpers.php';
try{ if($_SERVER['REQUEST_METHOD']!=='POST'){ApiResponse::send(false,[],'Method not allowed.',[],405);exit;} $db=automation_db(); $owner=automation_require_auth(); $data=automation_input(); automation_require_csrf($data); $id=(int)($data['automation_id']??0); $action=(string)($data['action']??'cancel'); if(!in_array($action,['cancel','enable','archive'],true)){ApiResponse::validation(['action'=>'Invalid action.']);exit;} $status=$action==='enable'?'scheduled':($action==='archive'?'cancelled':'cancelled'); $s=$db->prepare('UPDATE automation_rules SET status=:status WHERE id=:id AND owner_id=:owner AND deleted_at IS NULL');$s->execute(['status'=>$status,'id'=>$id,'owner'=>$owner]); if($s->rowCount()<1){ApiResponse::notFound('Automation not found.');exit;} ApiResponse::success([],$action==='enable'?'Automation enabled.':'Automation cancelled.'); }catch(Throwable $e){Logger::error('Automation status failed',['error'=>$e->getMessage()]);ApiResponse::serverError('Unable to update automation.');}
?>
